import React, { CSSProperties, useCallback } from 'react';
import { useIntl } from 'react-intl';

import { ArrowDownIcon, ArrowUpIcon } from '@dynatrace/strato-icons';

import { Button } from '../../../../buttons/button/Button.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { Tooltip } from '../../../../overlays/tooltip/Tooltip.js';
import { dataTableMessages } from '../../../DataTable/messages.js';
import { ColumnMinInstance } from '../../../types/internal-table-types.js';
import {
  getDisableMoveLeftAndRight,
  changeColumnOrder,
} from '../../../utils/column-order-utils.js';

/**
 * @internal
 */
export interface ColumnOrderSettingsProps {
  column: ColumnMinInstance;
  columns: ColumnMinInstance[];
  style: CSSProperties;
  onColumnsReordering: (columns: ColumnMinInstance[]) => void;
}
// #endregion Typings

/**
 * ColumnOrderControls component renders buttons inside the column settings modal located in the table toolbar.
 * Buttons are used for changing the order of the column.
 * @internal
 * @returns ColumnOrderSettings component
 */
export const _ColumnOrderControls = (props: ColumnOrderSettingsProps) => {
  const {
    column: currentColumn,
    columns: allColumns,
    onColumnsReordering,
    ...remainingProps
  } = props;

  const intl = useIntl();

  // index of the column or the first column with the respective header column
  const currentIndex = allColumns.findIndex(
    (col) => col.id === currentColumn.id || col.parent?.id === currentColumn.id,
  );

  const { disableMoveLeft, disableMoveRight } = getDisableMoveLeftAndRight(
    currentColumn,
    allColumns,
  );

  const handleColumnMoving = useCallback(
    (direction: 'left' | 'right') => {
      const columnsReordered = changeColumnOrder(
        direction,
        currentIndex ?? 0,
        currentColumn,
        allColumns,
      );

      onColumnsReordering(columnsReordered ?? []);
    },
    [currentIndex, currentColumn, allColumns, onColumnsReordering],
  );

  return (
    <Flex flexDirection="row" {...remainingProps} gap={4}>
      <Tooltip text={intl.formatMessage(dataTableMessages.moveColumnUpLabel)}>
        <Button
          aria-disabled={disableMoveLeft}
          aria-label={intl.formatMessage(dataTableMessages.moveColumnUpLabel)}
          size="condensed"
          onClick={() => {
            if (!disableMoveLeft) {
              handleColumnMoving('left');
            }
          }}
        >
          <Button.Prefix>
            <ArrowUpIcon />
          </Button.Prefix>
        </Button>
      </Tooltip>
      <Tooltip text={intl.formatMessage(dataTableMessages.moveColumnDownLabel)}>
        <Button
          aria-disabled={disableMoveRight}
          aria-label={intl.formatMessage(dataTableMessages.moveColumnDownLabel)}
          size="condensed"
          onClick={() => {
            if (!disableMoveRight) {
              handleColumnMoving('right');
            }
          }}
        >
          <Button.Prefix>
            <ArrowDownIcon />
          </Button.Prefix>
        </Button>
      </Tooltip>
    </Flex>
  );
};
